const write=(file,text)=>{fs.mkdirSync(path.dirname(path.join(root,file)),{recursive:true});fs.writeFileSync(path.join(root,file),text.trimStart().trimEnd()+'\n');};
const header=(active='',p='')=>`<header class="lab-header"><a class="lab-skip" href="#main">Skip to content</a><div class="lab-nav"><a class="lab-logo" href="${p}index.html"><span class="lab-monogram" aria-hidden="true">ai</span>The AI Explainer</a><nav class="lab-links" aria-label="Main navigation">${[['articles.html','Workflows'],['ai-background.html','AI cases'],['tools.html','Tools'],['downloads.html','Downloads'],['about.html','About']].map(([href,label])=>`<a href="${p}${href}"${active===href?' aria-current="page"':''}>${label}</a>`).join('')}</nav></div></header>`;
const footer=(p='')=>`<footer class="lab-footer"><div class="wrap"><div class="footer-grid"><div><strong>The AI Explainer</strong><p>Practical spreadsheet workflows, sample files, and clear checks for everyday business work.</p></div><nav class="footer-links" aria-label="Footer navigation">${[['methods.html','How we check examples'],['updates.html','Updates'],['editorial-policy.html','Editorial policy'],['privacy.html','Privacy'],['terms.html','Terms'],['copyright.html','Copyright'],['contact.html','Contact']].map(([url,label])=>`<a href="${p}${url}">${label}</a>`).join('')}</nav></div><div class="footer-bottom">Independent learning resources. All downloadable practice records are fictional. © 2026 The AI Explainer.</div></div></footer>`;
const head=(title,description,file,p='',article=false)=>`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>${esc(title)} | The AI Explainer</title><meta name="description" content="${esc(description)}"><meta name="robots" content="index,follow,max-image-preview:large"><meta name="google-adsense-account" content="${pub}"><meta name="theme-color" content="#176651"><link rel="canonical" href="${base}/${file==='index.html'?'':file}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="${article?'article':'website'}"><meta property="og:url" content="${base}/${file==='index.html'?'':file}"><meta name="twitter:card" content="summary"><link rel="stylesheet" href="${p}lab.css?v=20261104-2">${article?`<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=${pub}" crossorigin="anonymous"></script><script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'Article',headline:title,description,datePublished:article===true?date:article.published,dateModified:article===true?date:(article.modified||updated),author:{'@type':'Organization',name:'The AI Explainer',url:base+'/about.html'},publisher:{'@type':'Organization',name:'The AI Explainer',url:base},mainEntityOfPage:base+'/'+file}).replaceAll('<','\\u003c')}</script>`:''}</head>`;
const shell=(title,description,file,body,active='',article=false)=>{const p=file.includes('/')?'../':'';return head(title,description,file,p,article)+`<body class="lab">${header(active,p)}<main id="main">${body}</main>${footer(p)}</body></html>`;};
const lead=(eyebrow,title,description,crumb='')=>`<div class="page-lead">${crumb?`<p class="crumb">${crumb}</p>`:''}<p class="eyeline">${eyebrow}</p><h1>${title}</h1><p class="intro">${description}</p></div>`;
const cards=(items)=>`<div class="cards">${items.map((w,i)=>`<article class="lab-card"><span class="card-num">0${i+1} / ${w.category}</span><h3><a href="guides/${w.slug}.html">${w.title}</a></h3><p>${w.description}</p><div class="card-footer"><span>Sample files included</span><span>${w.time} min</span></div></article>`).join('')}</div>`;
const tools=[{slug:'csv-import-diagnostic',title:'CSV import diagnostic',category:'Inspect the source',description:'Spot leading zeros, long identifiers, uneven records, blanks, and formula-like text before importing.',kind:'diagnostic',guide:workflows[0],how:`<p>Paste CSV text or choose a UTF-8 file, check the delimiter, and run the inspection. Data stays in the page. A quoted comma or newline remains part of its field. Findings point to import decisions; they do not determine whether a transaction is valid.</p><p>Leading-zero IDs and long references should be imported as Text. Date-like values need an agreed convention. Blank fields need a business rule. Formula-like text should be inspected before a spreadsheet opens it.</p>`,example:'The sample contains 14 data records and 11 columns. Its quoted multiline note is one field. Findings can overlap on the same cell.'},
{slug:'order-list-comparison',title:'Order-list comparison',category:'Reconcile snapshots',description:'Find changed records, new or missing keys, and repeated-key groups across two exports.',kind:'compare',guide:workflows[1],how:`<p>Both files must have the same unique column names. Enter the exact key header, such as <code>order_id</code>. Column order can differ. Comparisons preserve spaces and are case-sensitive. Different text representations of an amount count as changes.</p><p>A repeated key in either file is marked for review. The tool never silently merges rows or chooses a winning record. Changed-field details show the before and after values. Expand repeated groups to inspect their records, and use the download for every source record in each group.</p>`,example:'The sample produces two unchanged keys, one changed key, one only in A, one only in B, and one repeated-key group. Six distinct keys account for six rows in A and five in B.'},
{slug:'mixed-date-review',title:'Mixed-date review',category:'Resolve the convention',description:'Flag ambiguous dates, choose a source convention, and keep invalid or missing values visible.',kind:'dates',guide:workflows[3],how:`<p>Enter the exact date-column header. Review ambiguity leaves values such as 03/04/2026 unresolved while accepting unambiguous numeric dates. Choose a verified day-first or month-first rule to apply that convention consistently to non-ISO dates.</p><p>Only numeric dates with a four-digit year and YYYY-MM-DD inputs are supported, from 1900 through 9999. Timestamps and timezone conversions are outside the tool's scope. The download is a review report; it does not overwrite the original data.</p>`,example:'The sample in Review ambiguity mode produces four converted dates, one ambiguous value, one invalid value, and one blank. With a fixed convention, conflicting values become invalid.'}];

tools.push({slug:'weekly-sales-reconciler',title:'Weekly sales reconciler',category:'Trace the whole report',description:'Calculate shipped sales from an order export and see why every source record is included, excluded, or unresolved.',kind:'sales',guide:workflows[2],how:`<p>Use a line-item CSV with order_id, line_id, order_date, sku, quantity, unit_price_rm, discount_rm, and status columns. Extra columns are retained in the source-record audit. Set an inclusive start date, an exclusive end date, and the verified source date convention. The eligible status is exactly Shipped.</p><p>Choose whether to remove all-field exact repeats only after confirming the source's row meaning. The sample loader enables removal because the fictional source deliberately contains one accidental repeated record. A conflicting order-plus-line key or an invalid required value makes the total unavailable until resolved.</p><p>Amounts use a decimal point, an optional RM prefix, and correctly grouped comma thousands separators. Prices and discounts are non-negative with at most two decimal places. Quantities are positive whole numbers. Discounts apply once per line. Refunds, returns, taxes, fees, and currency conversion are outside this tool's scope.</p>`,example:'Load the sample: 14 records reconcile to nine included lines, one exact repeat removed, two outside the date window, and two with other statuses. The result is RM267.60, 26 units, and eight orders.'});

