for(const folder of ['', 'articles','tools']){for(const file of fs.readdirSync(path.join(root,folder))){if(!file.endsWith('.html'))continue;const rel=folder?folder+'/'+file:file,p=folder?'../':'';let html=fs.readFileSync(path.join(root,rel),'utf8');html=html.replace(/<header class="site-header">[\s\S]*?<\/header>/,header('',p)).replace(/<footer class="site-footer">[\s\S]*?<\/footer>/,footer(p)).replace('<body>','<body class="legacy">').replace('</head>',`<link rel="stylesheet" href="${p}lab.css?v=20261104-2"></head>`).replaceAll('The AI Explainer Editorial Desk','The AI Explainer').replaceAll('ChatGPT vs Claude vs Gemini for Everyday Work','How to Compare AI Assistants for Everyday Work');
html=html.replace(/<h2>Editorial review note<\/h2>\s*<p>[\s\S]*?<\/p>/,'<h2>About this background guide</h2><p>This is a general AI literacy guide. For original sample data, worked calculations, and browser tools, visit the <a href="../articles.html">spreadsheet workflow collection</a>.</p>');
if(folder==='articles'){
  for(const heading of ['How to apply this guide','A safer prompt to try','About this background guide'])html=html.replace(new RegExp('<h2>'+heading+'</h2>[\\s\\S]*?(?=<h2>)'),'');
  html=html.replace(/\s*<li><a href="https:\/\/developers.google.com\/search\/docs\/fundamentals\/creating-helpful-content">[\s\S]*?<\/li>/g,'');

}
if(folder==='articles'){const count=(html.match(/<main[\s\S]*?<\/main>/)?.[0]||'').replace(/<[^>]*>/g,' ').split(/\s+/).length;html=html.replace(/\d+ min read/g,`${Math.max(3,Math.ceil(count/210))} min read`);}write(rel,html);}}
let legacyJS=fs.readFileSync(path.join(root,'script.js'),'utf8');legacyJS=legacyJS.replace('if (score >= 8)', 'if (checked.some((item) => Number(item.value) >= 3))').replace('} else if (score >= 4)', '} else if (score >= 2)');write('script.js',legacyJS);
