write('index.html',shell('Spreadsheet fixes you can check','Fix messy exports and build reliable reports with original practice files, worked examples, and free browser tools.','index.html',`<div class="wrap"><section class="home-hero"><div><p class="eyeline">Practical AI. Verifiable work.</p><h1>Messy spreadsheet.<br><em>Clear next step.</em></h1><p class="intro">Fix your export, check the numbers, and build a workflow you can use again. Start with complete examples you can download and follow.</p><div class="hero-actions"><a class="btn" href="guides/verified-weekly-sales-report.html">Build the weekly report <span aria-hidden="true">↗</span></a><a class="btn secondary" href="tools/csv-import-diagnostic.html">Check a CSV</a></div><p class="small-note">Free tools · Fictional practice data · No account needed</p></div><div class="sheet-demo" aria-label="Preview of the worked weekly sales example"><div class="demo-toolbar"><span>THE WORKED EXAMPLE</span><span>01 / WEEKLY SALES</span></div><div class="demo-title"><div>NET SHIPPED SALES<div class="demo-total">RM ${summary.net.toFixed(2)}</div></div><span>26 OCT – 01 NOV 2026</span></div><div class="demo-mini"><table><thead><tr><th>Product</th><th class="num">Units</th><th class="num">Net sales</th></tr></thead><tbody><tr><td>Notebooks</td><td class="num">8</td><td class="num">93.00</td></tr><tr><td>Pens</td><td class="num">13</td><td class="num">39.60</td></tr><tr><td>Mugs</td><td class="num">3</td><td class="num">70.00</td></tr><tr><td>Canvas bags</td><td class="num">2</td><td class="num">65.00</td></tr></tbody></table></div><div class="demo-status">14 source records → 1 exact repeat removed → 9 eligible lines</div></div></section><div class="stat-strip"><span><strong>10</strong> practical workflows</span><span><strong>${tools.length}</strong> browser tools</span><span><strong>1</strong> worked Excel report</span><span>Every example has a checkable result.</span></div><section class="section"><div class="section-heading"><div><p class="eyeline">Start with one task</p><h2>From export to answer.</h2></div><a href="articles.html">All workflows ↗</a></div>${cards(workflows.slice(0,3))}</section><section class="section"><div class="section-heading"><div><p class="eyeline">Use AI with a check</p><h2>From a plausible answer to an inspected result.</h2></div><a href="ai-background.html">All AI cases ↗</a></div><div class="cards">${[aiCases[6],aiCases[9],aiCases[15]].map(c=>`<article class="lab-card"><h3><a href="articles/${c.slug}.html">${esc(c.title)}</a></h3><p>${esc(c.description)}</p></article>`).join('')}</div></section></div><section class="tool-band"><div class="wrap section"><div class="section-heading"><div><p class="eyeline">A little help, right here</p><h2>Inspect. Compare. Reconcile.</h2></div><a href="tools.html">All tools ↗</a></div><div class="cards tool-grid">${tools.map((t,i)=>`<article class="lab-card"><span class="card-num">0${i+1} / ${t.category}</span><h3><a href="tools/${t.slug}.html">${t.title}</a></h3><p>${t.description}</p><div class="card-footer"><span>Files stay in your browser</span><span>Open tool ↗</span></div></article>`).join('')}</div></div></section><div class="wrap numbered-path"><div><p class="eyeline">The way we work</p><h2>Keep the source.<br>Show the work.<br>Check the result.</h2><p class="intro">Use AI to help explain a step or draft a formula. Keep a small known-answer example close by so you can tell whether it worked.</p><a class="btn secondary" href="methods.html">See how examples are checked</a></div><div class="path-steps">${[['01','Start from the original','Download the fictional input and see exactly what each record represents.'],['02','Make each decision visible','Choose types, date conventions, and duplicate rules before calculating.'],['03','Compare with a known answer','Use the worked file, expected totals, and boundary cases to verify the result.']].map(([n,t,d])=>`<div class="path-step"><span>${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></div>`));

write('articles.html',shell('Practical spreadsheet workflows','Ten specific spreadsheet workflows with original sample files and checkable outcomes.','articles.html',`<div class="wrap">${lead('The workflow collection','One problem.<br>A complete example.','Start with an import, reconcile a list, or build a checked weekly report. The files and expected results are included.')}<div class="compact-list">${workflows.map((w,i)=>`<article class="compact-item"><span>${String(i+1).padStart(2,'0')}</span><div><h3><a href="guides/${w.slug}.html">${w.title}</a></h3><p>${w.description}</p></div><span class="badge">${w.category}</span></article>`).join('')}</div><div class="legacy-note"><strong>Need AI background?</strong> The <a href="ai-background.html">AI case library</a> applies concepts, prompting, and privacy to distinct fictional tasks. The worked spreadsheet collection above is the best starting point for a task.</div><div class="section"></div></div>`,'articles.html'));

for(const w of workflows){const file=`guides/${w.slug}.html`;const body=`<div class="wrap">${lead(w.category,esc(w.title),esc(w.description),'<a href="../articles.html">Workflows</a> / Worked example')}<div class="article-grid"><article class="prose"><div class="meta"><span>The AI Explainer</span><span>Published November 4, 2026${w.modified?' · Updated November 13, 2026':''}</span><span>${w.time} min read</span><span><a href="../methods.html">Example &amp; verification method</a></span></div>${w.sections.map(([id,title,body])=>`<section aria-labelledby="${id}"><h2 id="${id}">${title}</h2>${body}</section>`).join('')}<section><h2 id="sources">Sources &amp; further reading</h2><ul class="source-list">${w.sources.map(([label,url])=>`<li><a href="${url}" rel="noopener">${label} — Microsoft</a></li>`).join('')}</ul><p class="small-note">The sample data and worked calculations are original instructional examples. Spreadsheet menus and supported features depend on your installed version. See the <a href="../methods.html">verification method</a> for the checks performed.</p></section><div class="callout"><p><strong>Continue the workflow</strong></p><p><a href="../tools/${w.tool}.html">Open the related browser tool ↗</a> · <a href="../downloads.html">Get the practice files</a></p></div></article><aside class="toc" aria-label="On this page"><strong>In this workflow</strong>${w.sections.map(([id,title])=>`<a href="#${id}">${title}</a>`).join('')}<a href="#sources">Sources</a><a class="btn secondary" href="../tools/${w.tool}.html">Open related tool ↗</a></aside></div></div>`;write(file,shell(w.title,w.description,file,body,'articles.html',{published:date,modified:w.modified||date}));}

const delimiter=`<div><label for="delimiter">Delimiter</label><select id="delimiter"><option value="auto">Detect from header</option><option value=",">Comma</option><option value=";">Semicolon</option><option value="&#9;">Tab</option></select></div>`;
const salesControls=`<div><label for="report-start">Start date (included)</label><input type="date" id="report-start"></div><div><label for="report-end">End date (excluded)</label><input type="date" id="report-end"></div><div><label for="convention">Source date convention</label><select id="convention"><option value="review">Review ambiguity</option><option value="dmy">Day / month / year</option><option value="mdy">Month / day / year</option></select></div><div class="repeat-choice"><label for="remove-repeats"><input type="checkbox" id="remove-repeats"> Remove all-field exact repeats after confirming they are accidental</label></div>`;
const input=(id,label)=>`<div><label for="${id}">${label}</label><textarea id="${id}" spellcheck="false" placeholder="Paste the header and CSV records here"></textarea><div class="file-control"><div><label for="file-${id}">Or choose a local UTF-8 file</label><input type="file" id="file-${id}" accept=".csv,.tsv,.txt,text/csv,text/plain" data-target="#${id}"></div></div></div>`;
for(const t of tools){let form=t.kind==='compare'?`<div class="two-inputs">${input('csv-a','File A — earlier snapshot')}${input('csv-b','File B — later snapshot')}</div>`:input('csv-input','CSV text');form+=`<div class="control-row">${delimiter}${t.kind==='sales'?salesControls:''}${t.kind==='compare'?'<div><label for="key">Exact key-column name</label><input type="text" id="key" value="order_id" autocomplete="off" spellcheck="false"></div>':''}${t.kind==='dates'?'<div><label for="date-column">Exact date-column name</label><input type="text" id="date-column" value="date" autocomplete="off" spellcheck="false"></div><div><label for="convention">Source date convention</label><select id="convention"><option value="review">Review ambiguity</option><option value="dmy">Day / month / year</option><option value="mdy">Month / day / year</option></select></div>':''}</div><div class="actions"><button type="button" class="btn" id="run">${t.kind==='compare'?'Compare records':t.kind==='dates'?'Review dates':t.kind==='sales'?'Reconcile sales':'Inspect CSV'}</button><button type="button" class="btn secondary" id="export" disabled>Download review report</button><button type="button" class="btn secondary" id="clear">Clear inputs</button></div><div id="result" class="tool-result" tabindex="-1" aria-live="polite" aria-atomic="false"></div>`;
const body=`<div class="wrap">${lead(t.category,t.title,t.description,'<a href="../tools.html">Tools</a> / '+t.title)}<div class="tool-shell" data-lab-tool="${t.kind}"><div class="tool-topline"><p>LOCAL PROCESSING · UP TO 5 MB / 10,000 DATA RECORDS PER FILE</p><button type="button" id="sample" class="btn secondary">Load fictional sample</button></div><noscript><p class="error-box">Enable JavaScript to use this browser-local tool. The downloadable examples and written guides remain available.</p></noscript>${form}<p class="tool-help">The tool processes file contents in browser memory and has no file-upload endpoint. The live host adds Cloudflare page and performance analytics. <a href="../privacy.html">Read the privacy details</a>. Choose files only on a device you trust.</p></div><div class="article-grid"><article class="prose"><h2 id="how">How to use this tool</h2>${t.how}<div class="callout"><p><strong>Check the built-in sample</strong></p><p>${t.example}</p></div><h2 id="limits">Limits and the downloaded report</h2><p>The parser supports comma, semicolon, and tab delimiters, quoted separators, escaped quotes, and multiline fields. It reads UTF-8 text, with an optional byte-order mark. An unclosed quote or an invalid field boundary stops processing. Large files should be handled in an appropriate local spreadsheet or data application.</p><p>Data remains in memory until you clear or leave the page. The tool does not save it to browser storage. Reports retain unresolved findings. Formula-like text is prefixed with an apostrophe in downloaded review reports; this is a deliberate report-only change. CSV does not define text column types, so import identifiers as Text.</p><h2 id="follow">Follow the complete example</h2><p><a href="../guides/${t.guide.slug}.html">${t.guide.title} ↗</a></p><p><a href="../methods.html">Read the calculation and tool verification method</a>.</p></article><aside class="toc"><strong>Use &amp; understand</strong><a href="#how">How it works</a><a href="#limits">Limits &amp; downloads</a><a href="#follow">Complete example</a></aside></div></div><script defer src="../tool-bundle.js?v=20261104-2"></script>`;write(`tools/${t.slug}.html`,shell(t.title,t.description,`tools/${t.slug}.html`,body,'tools.html'));}

