const downloadLabels={'orders-messy.csv':['Original order export','14 records. Exact repeated line, two-line order, statuses, and date boundaries.'],'orders-clean.csv':['Prepared order export','13 lines after removing the known exact repeated record. ISO date strings and plain amounts.'],'orders-report-lines.csv':['Included report lines','Nine Shipped lines within the reporting week.'],'orders-a.csv':['Comparison snapshot A','Six order-level records, including a repeated key.'],'orders-b.csv':['Comparison snapshot B','Five order-level records.'],'mixed-dates.csv':['Mixed-date practice','Ambiguous, invalid, blank, ISO, and leap-day examples.'],'import-edge-cases.csv':['CSV import edge cases','Leading zeros, long references, quoted commas, multiline notes, and formula-like text.'],'amounts-practice.csv':['RM amount practice','Known answers, a negative, zero, blank, and an unresolved decimal convention.'],'lookup-practice.csv':['Lookup-key practice','Spaces, a nonbreaking space, and a text identifier.'],'refresh-next-week.csv':['Second source for refresh','Two lines. Five units and RM85.00 net sales.'],'method-comparison.csv':['Blank method measurement log','Record your own setup, work, review time, and observed outcome.']};
write('downloads.html',shell('Practice files and worked workbook','Download original fictional CSV data, a formula-driven Excel report, and expected results for the workflow collection.','downloads.html',`<div class="wrap">${lead('Everything you need to follow along','Start with the file.<br>Finish with a checked result.','Original fictional data, a formula-driven workbook, and explicit expected outcomes. No email or account required.')}<div class="download-box"><h3>Weekly sales worked example</h3><p>Three sheets: Weekly report, prepared Orders, and the original Raw export. Formulas calculate the reporting window, line values, SKU totals, and distinct included orders.</p><a href="downloads/weekly-sales-worked-example.xlsx" download>Download the Excel workbook ↓</a><a href="guides/verified-weekly-sales-report.html">Follow the complete workflow ↗</a><p class="small-note">Expected week: October 26–November 1, 2026. Net sales RM267.60. No macros or external file connections.</p></div><div class="data-wrap"><table><thead><tr><th scope="col">Practice file</th><th scope="col">What it contains</th><th scope="col">Download</th></tr></thead><tbody>${Object.entries(downloadLabels).map(([file,[label,note]])=>`<tr><td>${label}</td><td>${note}</td><td><a href="downloads/${file}" download>CSV ↓</a></td></tr>`).join('')}<tr><td>Expected weekly results</td><td>Reporting window, row counts, units, gross, discount, and net totals.</td><td><a href="downloads/expected-results.json" download>JSON ↓</a></td></tr></tbody></table></div><section class="section prose"><h2>Power Query code and self-test</h2><p>Download the <a href="downloads/order-cleanup-function.pq" download>cleanup function</a>, <a href="downloads/order-cleanup-file.pq" download>file connection query</a>, and <a href="downloads/order-cleanup-self-test.pq" download>three-case self-test</a>. These are plain-text M code, not an Excel workbook. <a href="guides/repeatable-power-query-cleanup.html">Follow the setup and expected results</a>.</p><h2>AI practice cases</h2><p>Use the <a href="downloads/support-triage.csv" download>ticket-routing answer key</a>, <a href="downloads/email-brief.txt" download>delivery brief</a>, <a href="downloads/meeting-source.txt" download>meeting notes</a> and <a href="downloads/meeting-actions.csv" download>action register</a>, <a href="downloads/policy-source.txt" download>policy source pack</a>, and <a href="downloads/claim-audit.txt" download>claim-audit exercise</a>. All are original fictional teaching material. <a href="ai-background.html">Choose an AI case</a>.</p><h2>Using the files</h2><p>Every record and contact detail is fictional and created for these examples. You may use and adapt the practice data for learning and internal training. Attribution is appreciated. Third-party sources retain their own rights.</p><p>CSV has no spreadsheet column types. Import identifiers as Text and apply the declared date and decimal convention. The edge-case sample includes a deliberately formula-like note; inspect it through a text-typed import. The worked XLSX stores identifiers as text.</p><p>For a reusable workflow, read the guide's scope and test a second sample before replacing it with your own records. <a href="methods.html">See how the examples are checked</a>.</p></section></div>`,'downloads.html'));

const simple=(file,title,desc,body)=>write(file,shell(title,desc,file,`<div class="wrap">${lead('The AI Explainer',title,desc)}<div class="article-grid"><article class="prose">${body}</article></div></div>`,file==='about.html'?'about.html':''));
simple('about.html','Useful explanations start with a complete example.','The AI Explainer publishes practical spreadsheet workflows and careful uses of AI for everyday business work.',`<h2>What you will find here</h2><p>The site focuses on people who receive exports, reconcile lists, and prepare routine reports: office administrators, small-business operators, and anyone who needs a clear, repeatable spreadsheet process.</p><p>The workflow collection uses original fictional data, downloadable files, visible formulas, and expected answers. Browser tools support quick import checks, snapshot comparison, and date review. The <a href="ai-background.html">AI case library</a> connects AI concepts with routing, source checking, privacy, meeting notes and draft review. Each page has a distinct task or decision.</p><h2>Who is responsible</h2><p>The AI Explainer is an independent website owned and maintained by Shawn. Shawn is responsible for publication, maintenance, and corrections. Report a correction through the <a href="contact.html">feedback page</a>, with the page URL and a small fictional reproduction.</p><h2>How this collection was made</h2><p>AI assisted the creation of the workflow text, sample data, and code. The worked calculations and tool rules have reproducible checks. The examples do not represent a human expert's client work or a comparative benchmark of AI products. <a href="methods.html">The verification page</a> states the methods and their limits.</p><h2>Why the examples are small</h2><p>A small fictional dataset makes each decision visible. You can see why a repeated line is removed, why two lines still belong to one order, and why a boundary date changes a total. The goal is to make the check understandable before you apply a method to a larger file.</p>`);
simple('methods.html','How the examples are checked','Original sample data, explicit rules, and reproducible results make the workflows inspectable.',`<h2>The known-answer sales example</h2><p>The source contains 14 fictional records. Data record 5 exactly repeats record 4. The prepared set has 13 lines. The week starts October 26, 2026 and ends before November 2. Eligible status is Shipped. This leaves nine lines, eight distinct orders, 26 units, RM286.60 gross, RM19.00 discounts, and RM267.60 net.</p><p>The line arithmetic is checked independently in JavaScript and in the exported workbook's calculation engine. A quantity edit and a date-window edit are exercised and restored. The workbook is rendered for layout review, and identifiers are inspected as text in the exported file. A byte-identical copy was also opened in Excel for Windows: changing Orders G6 from 2 to 3 recalculated net sales to RM280.10 and units to 27 while distinct orders remained eight. The public workbook keeps the original quantity and RM267.60 result. <a href="downloads/expected-results.json">Download the expected results</a>.</p><h2>The browser tools</h2><p>Parser checks cover quoted commas, escaped quotes, multiline records, byte-order marks, semicolons, tabs, malformed quotes, mismatched widths, and size limits. Comparison checks cover changed values, column order, repeated keys, blanks, and exact matching. Date checks cover ambiguity, fixed conventions, leap days, invalid dates, and the supported year range. Sales-report checks reconcile every source record and verify exact cent arithmetic, known duplicates, conflicting line keys, invalid amounts, zero-price lines, and date boundaries. The comparison export retains field names and every repeated source record.</p><p>The tool application uses bundled local JavaScript and reads file text in browser memory, with no file-upload endpoint. The live hosting service injects Cloudflare Web Analytics; the earlier claim that the pages had no analytics was incorrect and was corrected on November 13, 2026. <a href="privacy.html">Read the current disclosure</a>. Review downloads apply an apostrophe to formula-like fields and retain unresolved findings. The original input file is not modified.</p><h2>AI practice cases and Power Query</h2><p>The AI library uses authored fictional scenarios and answer keys, not recorded model outputs, customer testimonials or product rankings. The Power Query page provides the exact M function and a self-test containing three fictional input cases. On November 13, 2026, all three M files passed syntax parsing with Microsoft’s @microsoft/powerquery-parser 5.0.0. This checks the language syntax, not function evaluation. Native Power Query execution and local-file refresh were not completed during this update; run the supplied self-test and refresh checks in your Excel version before relying on the query. Automated JavaScript checks verify the sample’s expected results independently.</p><h2>What the verification does not establish</h2><p>Formula-engine checks do not prove every menu path, Power Query step, or Excel version behaves identically. Power Query instructions refer to Microsoft's documentation and require checking in your installed version. These examples do not measure real-world AI speed or accuracy. The method-comparison log is blank for your own observed measurements.</p><h2>Corrections and changes</h2><p>Use the <a href="contact.html">feedback page</a> to report the URL, a fictional reproduction, expected outcome, and observed outcome. Reports use a public issue tracker; do not include private customer exports. A meaningful change should update the affected guide, its sample results, and the associated checks together.</p>`);
simple('editorial-policy.html','Editorial policy','How practical examples, sources, AI assistance, and corrections are handled.',`<p>Updated November 4, 2026.</p><h2>Publish a complete, useful task</h2><p>Workflow pages should state their input, assumptions, method, expected output, and limitations. Sample data must be clearly labeled fictional. Repeated general advice should not substitute for the page's promised example.</p><h2>Make evidence traceable</h2><p>Use official product documentation for feature-dependent claims and keep original calculations inspectable. A source link is background support; it does not replace testing a proposed formula or tool. State which checks were performed and avoid claiming tests that were not run.</p><h2>Use AI transparently</h2><p>AI may assist with writing, development, and sample creation. Do not invent personal experience, qualifications, user feedback, timings, screenshots, or product benchmark results. An illustrative faulty formula must be labeled as an instructional counterexample.</p><h2>Keep changes and advertising clear</h2><p>Correct substantive mistakes, update affected examples, and use honest publication dates. Advertising or commercial relationships must be distinguishable from tool controls and editorial recommendations. Tool pages in this collection do not load advertising scripts.</p><h2>Corrections</h2><p>Use the <a href="contact.html">feedback page</a> with a page URL and a specific fictional reproduction. See <a href="methods.html">how the examples are checked</a> for the current verification scope.</p>`);
simple('privacy.html','Privacy policy','How the site handles browser tools, hosting analytics, advertising, and public feedback.',`<p>Updated November 13, 2026.</p><h2>Files used in browser tools</h2><p>The four spreadsheet tools read pasted text or local files in browser memory. They do not upload file contents, store them in browser storage, or include them in URLs. The tool application has no file-upload endpoint and does not send CSV contents as part of its calculations. Tool pages do not include Google advertising scripts. Leaving or reloading the page clears the current tool state. Downloads are generated locally on your device.</p><h2>Cloudflare hosting analytics</h2><p>The live host injects Cloudflare Web Analytics into website pages, including the four spreadsheet tools. The beacon makes network requests to report visits and page-performance measurements. Cloudflare describes its collection in <a href="https://developers.cloudflare.com/web-analytics/data-metrics/data-origin-and-collection/">Data origin and collection</a> and its <a href="https://www.cloudflare.com/privacypolicy/">privacy policy</a>. These hosting requests are separate from the tool calculations. The prior statement that these pages loaded no analytics was corrected on November 13, 2026.</p><h2>Other website requests</h2><p>The hosting provider necessarily receives ordinary requests for pages and assets, including standard technical information such as IP address and browser information. Editorial article pages may load Google AdSense code. Some earlier helper pages also load Google-hosted fonts. Advertising services may use cookies or similar technologies for ad delivery and measurement.</p><p>Google explains its processing at <a href="https://policies.google.com/technologies/partner-sites">how Google uses information from sites that use its services</a>. Browser and Google account settings offer controls over cookies and ad personalization.</p><h2>Public feedback on GitHub</h2><p>Corrections and general questions use the <a href="https://github.com/ShawnT11/ShawnT11.github.io/issues">public repository issue tracker</a>. GitHub receives the account information and content you submit under its <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">privacy statement</a>. An issue, its comments and any attachments can be viewed by other people. Do not post private customer files, passwords, account details or personal information.</p><h2>Privacy questions</h2><p>Use the <a href="contact.html">feedback page</a> for general questions about this site. Keep any public question free of personal details. The linked Cloudflare and Google policies explain their own processing and available privacy controls.</p>`);
simple('contact.html','Feedback & corrections','Report a problem with a guide, sample file, or tool.',`<p>Shawn maintains this website. Corrections and general feedback are handled in the <a href="https://github.com/ShawnT11/ShawnT11.github.io/issues">public GitHub issue tracker</a>. A GitHub account is required to post.</p><p><a class="btn" href="https://github.com/ShawnT11/ShawnT11.github.io/issues/new">Report a correction on GitHub ↗</a></p><h2>What to include</h2><ul><li>The page URL and the step or sentence involved.</li><li>A small fictional example that reproduces the problem.</li><li>The expected result and what actually happened.</li><li>For spreadsheet issues, the app version, platform and relevant regional settings.</li></ul><h2>Reports are public</h2><p>Other people can read issues, comments and attachments. Do not post customer exports, credentials, account numbers, personal details or confidential business files. Replace real records with a minimal fictional example.</p><h2>Other questions</h2><p>Use the tracker for general questions about the site or its materials. For copyright concerns, give the affected page URL and identify the material without attaching private documents. Practice data may be adapted for learning and internal training; see the <a href="copyright.html">usage information</a>.</p>`);

for(const c of aiCases){
 const file='articles/'+c.slug+'.html';
 const count=c.sections.map(s=>s[2]).join(' ').replace(/<[^>]*>/g,' ').split(/\s+/).length;
 const body='<div class="wrap">'+lead(c.category,esc(c.title),esc(c.description),'<a href="../ai-background.html">AI cases</a> / Authored example')+'<div class="article-grid"><article class="prose"><div class="meta"><span>Maintained by Shawn</span><span>Updated November 13, 2026</span><span>'+Math.max(2,Math.ceil(count/190))+' min read</span></div><p class="small-note">Fictional practice case. The example prompts and answers are written for the exercise; they are not captured AI responses.</p>'+c.sections.map(([id,title,text])=>'<section aria-labelledby="'+id+'"><h2 id="'+id+'">'+title+'</h2>'+text+'</section>').join('')+(c.sources.length?'<section><h2 id="sources">Sources for the underlying concepts</h2><ul>'+c.sources.map(([label,url])=>'<li><a href="'+url+'">'+esc(label)+'</a></li>').join('')+'</ul></section>':'')+'<div class="callout"><p>AI assisted preparation of this collection. <a href="../methods.html">Read the verification scope</a> or <a href="../contact.html">report a correction</a>.</p></div></article><aside class="toc" aria-label="On this page"><strong>In this case</strong>'+c.sections.map(([id,title])=>'<a href="#'+id+'">'+title+'</a>').join('')+'<a href="../ai-background.html">All AI cases</a></aside></div></div>';
 write(file,shell(c.title,c.description,file,body,'ai-background.html',{modified:updated}));
}
write('ai-background.html',shell('AI case library','Original fictional exercises for AI concepts, source checking, privacy, prompts and everyday work.','ai-background.html','<div class="wrap">'+lead('AI case library','A clear question.<br>A checkable answer.','Practice with original fictional tickets, policy excerpts, meeting notes, briefs and spreadsheet cases. No invented product benchmarks or customer stories.')+'<p><a href="articles/ai-for-excel-users.html">New to using AI with Excel? Start with the checked-workflow introduction ↗</a></p><div class="compact-list">'+legacyArticles.map((a,i)=>'<article class="compact-item"><span>'+String(i+1).padStart(2,'0')+'</span><div><h3><a href="articles/'+a.file+'">'+esc(a.title)+'</a></h3><p>'+esc(a.description)+'</p></div><span class="badge">'+esc(a.category)+'</span></article>').join('')+'</div><div class="section"></div></div>'));
simple('updates.html','Updates and corrections','A dated record of substantive changes to the examples, tools and disclosures.',`<h2>November 13, 2026</h2><p>A wording audit corrected two stale instructions: comparison downloads now retain every repeated source record, and the sales reconciler now calculates a complete browser report. Removed the unverified contact email and replaced it with the public GitHub feedback tracker.</p><p>Reworked 21 AI articles into distinct authored cases with explicit answer keys. Added ticket-routing data, an email brief, a policy source pack, meeting notes and an action register, and a claim-audit exercise. Replaced overlapping introductory advice with task-specific decisions and checks.</p><p>Added downloadable Power Query M code and a three-case self-test to the CSV cleanup guide. Clarified the difference between the existing formula workbook and a refreshable query.</p><p>Corrected the privacy and tool descriptions: the live host injects Cloudflare Web Analytics, so the earlier no-analytics statement was inaccurate. The tool application continues to calculate in browser memory and has no CSV-upload endpoint.</p><h2>November 4, 2026</h2><p>Published the worked spreadsheet collection, original practice files and local browser tools. Added traceable sales reconciliation and identified Shawn as the site maintainer.</p><h2>Suggest a correction</h2><p><a href="contact.html">Send a page URL and a small fictional reproduction</a>. New updates should record actual changes; this page does not imply a fixed publishing schedule.</p>`);

simple('articles/ai-for-excel-users.html','AI for Excel users: start with a checked workflow','Use a small fictional spreadsheet example to judge a proposed formula or cleanup plan before applying it to real work.',`<h2>Start with a result you can check</h2><p>The workflow collection follows an original order export from 14 source records to a verified weekly report. It includes a deliberate repeated record, a legitimate two-line order, status exclusions, and date boundaries. The result is RM267.60 net sales across nine included lines and eight orders.</p><p><a href="../guides/verified-weekly-sales-report.html">Build the weekly sales report</a> and <a href="../downloads/weekly-sales-worked-example.xlsx" download>download the worked workbook</a>.</p><h2>Give AI a bounded task</h2><p>Ask an assistant to explain a formula, draft a transformation plan, or suggest edge cases. Provide fictional column names and a small sample. Keep the source record meaning, final calculations, and expected result visible in your spreadsheet.</p><p><a href="../guides/verify-ai-generated-spreadsheet-formulas.html">Test a proposed formula against a known answer</a>. The guide includes an incomplete candidate that misses the reporting window and a corrected set of criteria.</p><h2>Import correctly before calculating</h2><p>Order IDs and phone numbers should remain text. Dates need a confirmed source convention. Amounts must be numeric before arithmetic. A formula applied to damaged imports can produce a precise-looking answer from the wrong inputs.</p><p><a href="../guides/import-order-csv-without-damaging-data.html">Follow the typed-import example</a>, or <a href="../tools/csv-import-diagnostic.html">inspect an export locally</a>.</p><h2>Measure the whole workflow</h2><p>Include setup, prompting, corrections, and review when judging whether assistance saves time. Use the same source and target result for each method. The <a href="../guides/choose-spreadsheet-cleanup-method.html">method-comparison guide</a> includes a blank measurement log for your own observations.</p>`);

const htmlFiles=[];for(const dir of ['','articles','guides','tools'])for(const file of fs.readdirSync(path.join(root,dir)))if(file.endsWith('.html'))htmlFiles.push(dir?dir+'/'+file:file);
write('sitemap.xml',`<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">${htmlFiles.map(file=>{const html=fs.readFileSync(path.join(root,file),'utf8');const modified=html.match(/"dateModified":"([^\"]+)"/)?.[1]||(['index.html','articles.html','tools.html','downloads.html','about.html','contact.html','editorial-policy.html','terms.html','copyright.html','methods.html','privacy.html','ai-background.html','updates.html','tools/csv-import-diagnostic.html','tools/order-list-comparison.html','tools/mixed-date-review.html','tools/weekly-sales-reconciler.html'].includes(file)?updated:date);return `<url><loc>${base}/${file==='index.html'?'':file}</loc><lastmod>${modified}</lastmod></url>`;}).join('')}</urlset>`);
write('README.md',`# The AI Explainer workflow collection\n\nBuild with Node.js 20 or later: \`node build-site.mjs\`. Run meaningful data-tool checks with \`node --test tests/*.test.mjs\`. Preview with \`node preview-server.mjs\`.\n\nOpen index.html directly to use the completed site, including its browser tools. A local HTTP preview is optional.\n\nThe site is static and keeps the existing domain, publisher meta tag, and ads.txt. It adds ten workflow guides, four browser-local tools, 21 AI cases, thirteen CSV practice files plus authored text exercises and three Power Query M files, expected results, and one formula-driven XLSX. The tool application loads no advertising; the live hosting layer injects Cloudflare Web Analytics, disclosed on privacy.html. All practice data is fictional.\n\nThe builder runs build-legacy.mjs to retain the existing article URLs, then applies the shared navigation and new collection. Edit content/workflows.mjs for spreadsheet guides, content/ai-cases.mjs for the AI case library, content/power-query-guide.mjs for Power Query instructions, and build-site.mjs for page structure. The worked XLSX and its actual renders are committed static assets. Its authoring script uses the bundled artifact-tool runtime outside the deployable site.\n\nThe workbook formula engine was checked against independent calculations and representative input edits. Power Query M downloads passed Microsoft parser 5.0.0 syntax checks; native M execution was not completed. Follow the supplied self-test and local-file refresh steps in your Excel version. The XLSX has no embedded query. No live deployment or AdSense review is performed by this build.\n\nFor existing GitHub Pages hosting, publish the static files at repository root using the existing deployment process. Keep .git unchanged. No framework build or backend is required.\n`);
console.log(JSON.stringify({workflows:workflows.length,newTools:tools.length,htmlPages:htmlFiles.length,sampleCsvs:Object.keys({...files,...caseDownloads}).filter(n=>n.endsWith('.csv')).length,expected:summary}));
